  "msw.label": "Ranking",
  "msw.tip": "Two rankings from the same results: the official CN, published by the FFCO, and the Ozimut index, calculated by this site.",
  "m.official.tip": "Official: the CN published by FFCO (mean of the best races, rescaled every 1 January).",
  "m.top6w.tip": "Ozimut: an Ozimut score per race (the course's Ozimut value — the mean of the usual levels × times of the fastest: 90% of the field in forest, two thirds in sprint — divided by the runner's time), then the runner's Ozimut index, the weighted mean of their best races over 6 places. Calculated on the same results as the official CN.",
  "m.fair.tip": "The runner's usual level — the weighted mean of their best 60% of Ozimut scores, with no cap on places —, the one against which courses' Ozimut values are measured.",
  "m.fair.long": "The runners' usual level, the weighted mean of their best races, with no cap on places; course values are measured against it",
  "m.top6w.long": "An Ozimut score per race, an Ozimut index per runner: the weighted mean of their best races over 6 places; courses measured on the fastest of the field (90% in forest, two thirds in sprint)",
