  "rl.model": "The model: on a leg, a runner for whom {cnThe} is c takes k × reference time ÷ c; k is set so that the best team of all clubs (for the CNE, the mean of the 5 best) totals the sum of the reference times, as FFCO requires. The best team is calculated exactly, composition criteria and reserved legs included (2026 competition rules). Age and sex come from the runner's class: a veteran running M21 counts as an M21.",
