  "cfc.rule": "Rule (2026 competition rules, appendix 2): each runner brings their club the sum of their 5 best official CN scores of the year on foot (forest and sprint), plus their 5 best in MTB or ski; a woman's points are multiplied by 1.4. Ozimut's calculation, unofficial: every ranked runner counts (the licence type is not known), and a runner who changed club during the year counts for the club of their last race. * The cup was not awarded from 2023 to 2025.",
