  "spl.grp.title": "Running in groups",
  "spl.grp.ctl": "controls",
  "spl.grp.hint1": "From the 1st to the last control: two runners, from any course, who left the same control and reached the next one less than",
  "spl.grp.hint2": "s apart ran the leg together; click a header to sort",
  "spl.grp.none": "No start times for this course: groups cannot be detected (WinSplits, liveresultat and IOF XML files give them).",
  "spl.grp.legs": "Legs in a group",
  "spl.grp.pack": "Share in a group",
  "spl.grp.front": "In front",
  "spl.grp.behind": "Behind",
  "spl.grp.follow": "Share behind",
  "spl.grp.gain": "Gained behind",
  "spl.grp.with": "With",
  "spl.grp.map": "Group map",
  "spl.grp.map.hint": "Per leg, the number of runners in company; green: the runner punches first, red: behind. Hover over a cell to see with whom",
  "spl.grp.def": "Share in a group, share behind: the time of the legs run in a group, and behind another runner, relative to the time run from the 1st to the last control (the start and the finish, where runners are apart or all together, do not count). Gained behind: on the legs run behind, the time gained on the runner's usual pace (negative: lost). The controls under “With” are those between which the runners ran together.",
  "spl.sum": "Summary per runner",
  "spl.sum.hint": "Click a header to sort",
  "spl.won": "Legs won",
  "spl.avgRank": "Average rank",
  "spl.lostPct": "Share lost",
  "spl.pace": "Usual pace",
  "spl.reg": "Irregularity",
  "spl.kmPace": "Min/km",
  "spl.sum.def": "Legs won: the best times. Average rank: on the legs. Share lost: the time lost relative to the race time. Usual pace: the gap to the best time on the legs run without a mistake (the runner's time over the sum of the best times). Irregularity: the spread of the gaps to the best (coefficient of variation); the lower it is, the more even the race. Duels won: the runners on the course beaten on more legs than they won.",
  "prov.seeSplits": "View",
  "spl.def": "Time lost: on each leg, the gap between the runner's time and their “ideal” time: the leg's reference time (the mean of the fastest sixth, the winner left out; under 12 times the mean of the two best, under 5 the best) multiplied by their usual pace, their time on the legs run without a mistake over those legs' reference times — a long leg counts more than a short one. This is time lost as MeOS and WinSplits compute it, which inspired most of the views on this page.",
  "spl.tab.clock": "Passings",
  "spl.tab.follow": "Autonomy",
  "spl.tab.regular": "Regularity",
  "spl.start": "Start",
  "spl.startAbbr": "S",
  "spl.finishAbbr": "F",
  "spl.table.marks": "Orange frame: a time the checks above find doubtful (hover over the cell).",
  "spl.table.followed": "Coloured bar on the left: a leg run behind another runner (see “Autonomy”).",
  "spl.clk.all": "All runners",
  "spl.clk.sel": "Compared runners only",
  "spl.clk.title": "Passing times chart",
  "spl.clk.hint": "Each line: a runner, control after control, at the time of day they passed it. Lines that meet: runners together; a steeper line: a runner catching others up. Scroll to zoom; pick the runners in colour under the chart",
  "spl.sc.pts": "Points",
  "spl.sc.pts.hint": "The sum of the points of the controls taken, as their names give them (“206 (1p)”), without late penalties",
  "spl.sc.rank": "Score race: ranked by the points of the controls taken (their number when they carry no points), then by time; without the late penalties, which depend on the organiser's rules",
  "spl.sc.leg": "Since the previous control: {t}",
  "spl.sc.hint": "Score race: each runner chooses their controls and their order, so there are no legs to compare. For each runner, their controls in the order taken, with the time since the start; hover over a control for the time since the previous one",
  "spl.clk.hint.score": "Score race: each line follows a runner, the number of controls taken since the start at the time of each punch, the finish on the level of the last control. Lines that merge: runners together; a steeper line: a runner taking controls in quick succession. Scroll to zoom; pick the runners shown in colour under the chart",
  "spl.clk.def": "The times are the passing times: the start time plus the cumulative time at each control. Only the runners whose start time is known are drawn ({n} of {of}).",
  "spl.clk.none": "No start times for this course: the passings cannot be placed in time (WinSplits, liveresultat and IOF XML files give them).",
  "spl.fol.thr": "Together within",
  "spl.fol.t1": "Gap in seconds up to which two runners are fully together",
  "spl.fol.t2": "Gap in seconds beyond which they are no longer together",
  "spl.fol.t1u": "s, then less and less up to",
  "spl.fol.t2u": "s",
  "spl.fol.title": "Autonomy: who followed whom",
  "spl.fol.hint": "On each leg, two runners of the course who left the same control less than {t2} s apart: together where less than {t1} s separate them, less and less up to {t2} s. The second one to pass follows the first. Click a header to sort",
  "spl.fol.def": "Follower index: the time run behind another runner minus the time run in front, as a share of the time of the legs counted (positive: rather a follower, negative: rather a leader). Between two controls each runner is assumed to move at a steady speed: this is an estimate, and a runner close in time is not necessarily followed (they may have taken another route). Start times are needed; only the legs where both times are known count. A leg is “behind” or “in front” for more than half of its time.",
  "spl.fol.none": "No start times for this course (or a single runner): who ran with whom cannot be told.",
  "spl.fol.index": "Follower index",
  "spl.fol.index.hint": "Time behind minus time in front, as a share of the race time",
  "spl.fol.behindT": "Behind",
  "spl.fol.aheadT": "In front",
  "spl.fol.legsBehind": "Legs behind",
  "spl.fol.legsAhead": "Legs in front",
  "spl.fol.main": "Main companion",
  "spl.fol.wasBehind": "behind {t}",
  "spl.fol.wasAhead": "in front {t}",
  "spl.fol.cell": "Run behind {who}",
  "spl.reg.chart": "Spread on each leg",
  "spl.reg.chartHint": "How far the runners strayed from their own level on this leg, in points: the highest bars are the legs where everyone ran unlike themselves",
  "spl.reg.title": "Runners' regularity",
  "spl.reg.hint": "Over {n} of the {of} runners: those who finished with all their split times. Click a header to sort",
  "spl.reg.def": "Performance index on a leg: its reference time (the mean of the best quarter of times) divided by the runner's time; 100%: as fast as the best, 50%: twice as slow. Irregularity: the standard deviation of these indices, each leg weighing its reference time (a long leg says more than a short one), relative to the runner's mean index (10 points weigh more for someone running at 40% than at 90%); the lower, the steadier the race. A leg's spread is that of the runners' indices relative to their own mean: with each one's level set aside, it shows where everyone varied.",
  "spl.reg.none": "Nobody finished this course with all their split times: regularity cannot be computed.",
