  "os.help.title": "Formats accepted",
  "os.help.best": "Best:",
  "os.help.best.text": "the IOF XML 3.0 “StartList” export from your software (OE, MeOS, OS…); everything is in it, unambiguously.",
  "os.help.csv": "CSV:",
  "os.help.csv.text": "a header row, then one runner per row. Columns recognised, in any order: Start (or Heure, Départ), Surname (or Nom), First name (or Prénom; or the whole name in one column), Club, Course (or Circuit), Class (or Catégorie). The time and the name are enough; without a Course column, the list is grouped by class. Separator semicolon, comma or tab. Example:",
  "os.help.csv.example": "Course;Start;Surname;First name;Club;Class\nPurple long;10:00;DUPONT;Jeanne;0109;D21\nPurple long;10:02;MARTIN;Paul;7707;H35\nOrange;10:01;LEROY;Léa;0111;D16",
  "os.help.csv.notes": "Times as 10:02 or 10h02 (or 10:02:30). Club: its number, possibly followed by its name, helps to recognise the runners. CSV exports from OE and MeOS are read too.",
  "os.help.sheet": "Google Sheets:",
  "os.help.sheet.text": "paste the link to the sheet, shared with “Anyone with the link”. It can follow the CSV layout above, or a grid: a row with the courses' names, then a Start / Name / Club header repeated for each course, one start per row:",
  "os.help.sheet.example": "         Purple long          Orange\nStart    Name          Club   Name         Club\n10:00    Jeanne DUPONT 0109   Léa LEROY    0111\n10:02    Paul MARTIN   7707\nOne Start column per course works too.",
  "os.help.else": "Otherwise:",
  "os.help.else.text": "your software's HTML pages, or OE's and MeOS's PDFs. For an Excel sheet, save it as CSV.",
