  "sh.e.drop.hint": "map: image, PDF or KMZ · georeferencing: KMZ/KML, world file (+ .prj) · course: IOF XML (Purple Pen, OCAD, Condes) · or your own GPX/TCX/FIT track on this course, used to georeference the map · or an OCAD course-setting file, which gives every course at once",
