  "ia.data": "The data",
  "ia.lede": "Ask a question about the rankings, results or clubs: an AI writes the query, your browser runs it on the site's data and turns it into a table or a chart.",
  "ia.placeholder": "For example: my forest Ozimut index month by month since 2024",
  "ia.model.tip": "The model that writes the query",
  "ia.ask": "Ask",
  "ia.note": "Free, within about a hundred questions a day for the whole site (15 per person per day; no limit with your own key, below). The AI doesn't see the data: it writes a query, which your browser runs. It can be wrong: the interpretation chosen and the query are shown under each answer.",
  "ia.byok.summary": "Your own API key: Claude, ChatGPT, Gemini or OpenRouter",
  "ia.byok.intro": "A more powerful model, at your own cost: your browser calls it directly with your key.",
  "ia.byok.provider": "Provider",
