  "ia.byok.load": "Load the models",
  "ia.byok.use": "Use",
  "ia.byok.forget": "Forget the key",
  "ia.byok.privacy": "The key stays in this browser: it is never sent to Ozimut (without “Remember”, it is erased when the tab closes; it is also erased when you log out). The provider receives the question, the description of the tables and your licence number — never the data —, under its terms, and charges you at its rates (a question costs from less than a cent to about a cent). Create a key reserved for this use, with a spending limit: a script on the page could read it.",
