  // IA, own key (askbyok.js)
  "byok.note.openrouter": "One key for most models (Claude, GPT, Gemini, Llama…), a spending cap per key. The free models are limited to 50 requests a day (1,000 after buying 10 credits) and 20 a minute — a question makes one, two if the query is corrected —; some of their providers may use the questions: see your OpenRouter account's privacy settings.",
