  "st.arenaM.hint": "The official CN or the Ozimut index in Arena's results, live races and runner windows: the value 15 days before the race, the scores and the expected place. In Stats, the choice is made at the top of the pages. Kept on this device.",
  "st.orga.title": "Modules", "st.orga.label": "Use the Orga module",
