  // Coach's analyses, one page each (owner, 2026-10-30)
  "coach.solo.race": "A competition", "coach.solo.free": "A training session or another race",
  "coach.multi.race": "Competitions", "coach.multi.club": "Training",
  "sh.mine.tip": "You organise it: manage it in the Orga module.",
  "cty.need.guest": "Without an account, Stats shows the runner, the ranking and the races over the period the federation publishes openly. Create an account and join France to see everything.",
  // the home page in four modules (owner, 2026-10-30)
  "tour.mod.try": "Try {mod} without an account", "tour.mod.orga.cta": "Create an account to organise",
  "tour.mod.arena.title": "The whole race, before, during and after",
  "tour.mod.arena.lede": "Arena gathers every competition in one place: the calendar and its entries, start times as soon as they are out, live results control by control, then the organisers' results, often the same evening, with the full split-time analysis. Pick a race, Arena does the rest.",
  "tour.mod.stats.title": "The ranking, readable at last",
  "tour.mod.stats.lede": "Stats puts all of orienteering into numbers: your index and your place, the exact detail of every calculation, your progress season after season on an index that compares from one year to the next since 2010, the clubs, the relays and the country's trends. Compare yourself, follow your rivals, understand every point won or lost.",
  "tour.mod.coach.title": "Improve between two races",
  "tour.mod.coach.lede": "Coach turns your tracks into lessons: replay your race on your map, see where the seconds slip away, compare your route choices with others'. Revise the control descriptions, train your map reading with twelve games and work out your VMA.",
  "tour.mod.coach.lede.lim": "Coach turns your tracks into lessons: replay your race on your map, see where the seconds slip away, compare your route choices with others'. Train your map reading with twelve games and work out your VMA.",
  "tour.mod.orga.title": "Organise without wearing yourself out",
  "tour.mod.orga.lede": "Orga gives clubs the tools for race day and after: set courses in the browser, publish start lists and results, broadcast live from MeOS, check the times and give runners their map analysis. Turn it on when you register or in your settings, on a computer.",
  "tour.feat.eyebrow": "Pricing", "tour.feat.title": "Everything is free, module by module",
  "tour.feat.lede": "Each row adds to the one above. Without an account Ozimut shows what is public; an account opens alerts and track sharing, and the Orga module the organisers' tools. What carries an asterisk also needs a federation's licence.",
  "tour.feat.note": "For a federation's licensees only: in France, an account that joined France, its FFCO licence number checked against the name. Countries whose results are all public (Spain) are open to everyone.",
  "tour.feat.star": "Federation licensees",
  "hub.guest.enter": "Enter without an account",
  "home.guest.or": "or", "home.guest.hint": "Without an account, many features are for registered users only: most advanced features are not shown.",
  // the home page's new pictures (2026-10-30)
  "tour.cap.hub.b": "Four modules,", "tour.cap.hub": "to choose on arrival: the logo brings you back at any time.",
  "tour.cap.past.b": "Past competitions,", "tour.cap.past": "with what Ozimut found of each.",
  "tour.cap.descriptions.b": "Control descriptions,", "tour.cap.descriptions": "in 23 languages, with a mode to practise.",
